// CPU-only independent Reference A (accelerated BVH) and Reference B (brute force).
// All ray/triangle arithmetic is double precision and this binary never imports Habitat.
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
struct V {float x,y,z,nx,ny,nz;uint8_t r,g,b;} __attribute__((packed));
struct P {double x,y,z;};
static P sub(P a,P b){return{a.x-b.x,a.y-b.y,a.z-b.z};} static P add(P a,P b){return{a.x+b.x,a.y+b.y,a.z+b.z};} static P mul(P a,double s){return{a.x*s,a.y*s,a.z*s};}
static double dot(P a,P b){return a.x*b.x+a.y*b.y+a.z*b.z;} static P cross(P a,P b){return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};} static double len(P a){return std::sqrt(dot(a,a));}
struct T {uint32_t a,b,c,id;}; struct N {double lo[3],hi[3];int left=-1,right=-1,begin=0,count=0;};
struct R {std::string frame,tags,role;int x=0,y=0;bool joint=false,rgb=false,key=false;P o,d;};
struct H {bool hit=false,front=false,back=false;double t=std::numeric_limits<double>::infinity(),u=0,v=0;uint32_t id=0;P n{};};
struct DSU {std::vector<uint32_t>p;DSU(size_t n):p(n){std::iota(p.begin(),p.end(),0);}uint32_t f(uint32_t x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}void u(uint32_t a,uint32_t b){a=f(a);b=f(b);if(a!=b)p[b]=a;}};
struct E {uint64_t k;uint8_t d;bool operator<(E const&o)const{return k<o.k;}};
struct C {uint64_t v=0,f=0;P lo{1e300,1e300,1e300},hi{-1e300,-1e300,-1e300};};
class M {public:
 std::vector<V>v;std::vector<T>t;std::vector<N>n;std::vector<uint32_t>cid,tcid;std::vector<C>cs;uint64_t source_faces=0,nontriangular_source_faces=0,finitev=0,normalfinite=0,invalid=0,deg=0,dupf=0,dupv=0,boundary=0,nonman=0,winding=0;double volume=0;P lo{1e300,1e300,1e300},hi{-1e300,-1e300,-1e300};
 P p(uint32_t i)const{auto&q=v[i];return{q.x,q.y,q.z};} bool valid(T const&q)const{return q.a<v.size()&&q.b<v.size()&&q.c<v.size();}
 void load(std::string const&path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("mesh_open_failed");std::string s;uint64_t nv=0,nf=0;while(std::getline(f,s)){if(s.rfind("element vertex ",0)==0)nv=std::stoull(s.substr(15));if(s.rfind("element face ",0)==0)nf=std::stoull(s.substr(13));if(s=="end_header")break;}if(!nv||!nf)throw std::runtime_error("unsupported_ply_header");source_faces=nf;v.resize(nv);f.read((char*)v.data(),sizeof(V)*nv);if(!f)throw std::runtime_error("vertex_read_failed");t.reserve(nf);for(uint64_t k=0;k<nf;k++){uint8_t count=0;f.read((char*)&count,1);if(!f||count<3)throw std::runtime_error("invalid_face_list");std::vector<uint32_t>ix(count);f.read((char*)ix.data(),sizeof(uint32_t)*count);if(!f)throw std::runtime_error("face_read_failed");if(count!=3)nontriangular_source_faces++;for(uint8_t q=1;q+1<count;q++)t.push_back({ix[0],ix[q],ix[q+1],(uint32_t)t.size()});}for(auto&q:v){P z{q.x,q.y,q.z};if(std::isfinite(z.x)&&std::isfinite(z.y)&&std::isfinite(z.z)){finitev++;lo={std::min(lo.x,z.x),std::min(lo.y,z.y),std::min(lo.z,z.z)};hi={std::max(hi.x,z.x),std::max(hi.y,z.y),std::max(hi.z,z.z)};}if(std::isfinite(q.nx)&&std::isfinite(q.ny)&&std::isfinite(q.nz))normalfinite++;}}
 void topo(){DSU d(v.size());std::vector<char>used(v.size());std::vector<E>es;es.reserve(t.size()*3);std::vector<std::array<uint32_t,3>>faces;std::vector<std::array<uint32_t,3>>verts;faces.reserve(t.size());verts.reserve(v.size());for(auto&q:t){if(!valid(q)){invalid++;continue;}P a=p(q.a),b=p(q.b),c=p(q.c),nn=cross(sub(b,a),sub(c,a));if(!std::isfinite(a.x+b.x+c.x+a.y+b.y+c.y+a.z+b.z+c.z)||len(nn)<=1e-12){deg++;continue;}d.u(q.a,q.b);d.u(q.a,q.c);used[q.a]=used[q.b]=used[q.c]=1;volume+=dot(a,nn)/6.;auto edge=[&](uint32_t x,uint32_t y){uint32_t l=std::min(x,y),h=std::max(x,y);es.push_back({(uint64_t(l)<<32)|h,(uint8_t)(x==l)});};edge(q.a,q.b);edge(q.b,q.c);edge(q.c,q.a);auto z=std::array<uint32_t,3>{q.a,q.b,q.c};std::sort(z.begin(),z.end());faces.push_back(z);}std::sort(es.begin(),es.end());for(size_t i=0;i<es.size();){size_t j=i+1;while(j<es.size()&&es[j].k==es[i].k)j++;if(j-i==1)boundary++;else if(j-i>2)nonman++;else if(es[i].d==es[i+1].d)winding++;i=j;}for(auto&q:v){uint32_t a,b,c;std::memcpy(&a,&q.x,4);std::memcpy(&b,&q.y,4);std::memcpy(&c,&q.z,4);verts.push_back({a,b,c});}std::sort(verts.begin(),verts.end());for(size_t i=1;i<verts.size();i++)if(verts[i]==verts[i-1])dupv++;std::sort(faces.begin(),faces.end());for(size_t i=1;i<faces.size();i++)if(faces[i]==faces[i-1])dupf++;cid.assign(v.size(),UINT32_MAX);std::unordered_map<uint32_t,uint32_t>id;for(size_t i=0;i<v.size();i++)if(used[i]){auto it=id.emplace(d.f(i),id.size()).first;cid[i]=it->second;}cs.resize(id.size());for(size_t i=0;i<v.size();i++)if(cid[i]!=UINT32_MAX){auto&c=cs[cid[i]];P z=p(i);c.v++;c.lo={std::min(c.lo.x,z.x),std::min(c.lo.y,z.y),std::min(c.lo.z,z.z)};c.hi={std::max(c.hi.x,z.x),std::max(c.hi.y,z.y),std::max(c.hi.z,z.z)};}tcid.assign(t.size(),UINT32_MAX);for(auto&q:t)if(valid(q)&&cid[q.a]!=UINT32_MAX){tcid[q.id]=cid[q.a];cs[cid[q.a]].f++;}}
 void box(int b,int e,N&z){for(int a=0;a<3;a++){z.lo[a]=1e300;z.hi[a]=-1e300;}for(int i=b;i<e;i++)for(uint32_t q:{t[i].a,t[i].b,t[i].c}){P x=p(q);z.lo[0]=std::min(z.lo[0],x.x);z.lo[1]=std::min(z.lo[1],x.y);z.lo[2]=std::min(z.lo[2],x.z);z.hi[0]=std::max(z.hi[0],x.x);z.hi[1]=std::max(z.hi[1],x.y);z.hi[2]=std::max(z.hi[2],x.z);}}
 int build(int b,int e){int k=n.size();n.push_back({});n[k].begin=b;n[k].count=e-b;box(b,e,n[k]);if(e-b<=8)return k;double dx[3]={n[k].hi[0]-n[k].lo[0],n[k].hi[1]-n[k].lo[1],n[k].hi[2]-n[k].lo[2]};int ax=dx[1]>dx[0]?1:0;if(dx[2]>dx[ax])ax=2;int m=(b+e)/2;std::nth_element(t.begin()+b,t.begin()+m,t.begin()+e,[&](T const&a,T const&b){P x=mul(add(add(p(a.a),p(a.b)),p(a.c)),1./3.),y=mul(add(add(p(b.a),p(b.b)),p(b.c)),1./3.);return ax==0?x.x<y.x:ax==1?x.y<y.y:x.z<y.z;});int left=build(b,m),right=build(m,e);n[k].left=left;n[k].right=right;return k;}
 bool aabb(N const&z,R const&r)const{double a=.05,b=20.;for(int k=0;k<3;k++){double o=k==0?r.o.x:k==1?r.o.y:r.o.z,d=k==0?r.d.x:k==1?r.d.y:r.d.z;if(std::abs(d)<1e-18){if(o<z.lo[k]||o>z.hi[k])return false;}else{double x=(z.lo[k]-o)/d,y=(z.hi[k]-o)/d;if(x>y)std::swap(x,y);a=std::max(a,x);b=std::min(b,y);if(b<a)return false;}}return true;}
 void one(T const&q,R const&r,H&h)const{P a=p(q.a),b=p(q.b),c=p(q.c),e1=sub(b,a),e2=sub(c,a),pv=cross(r.d,e2);double det=dot(e1,pv);if(std::abs(det)<1e-14)return;double inv=1/det,u=dot(sub(r.o,a),pv)*inv;if(u<0||u>1)return;P qq=cross(sub(r.o,a),e1);double w=dot(r.d,qq)*inv;if(w<0||u+w>1)return;double tt=dot(e2,qq)*inv;if(tt<.05||tt>20)return;P nn=cross(e1,e2);bool fr=dot(r.d,nn)<0;if(tt<h.t){h.hit=true;h.t=tt;h.u=u;h.v=w;h.id=q.id;h.n=mul(nn,1/len(nn));}if(fr)h.front=true;else h.back=true;}
 H cast(R const&r)const{H h;std::vector<int>s{0};while(!s.empty()){int k=s.back();s.pop_back();auto&z=n[k];if(!aabb(z,r))continue;if(z.left<0){for(int i=z.begin;i<z.begin+z.count;i++)one(t[i],r,h);}else{s.push_back(z.left);s.push_back(z.right);}}return h;}H brute(R const&r)const{H h;for(auto&q:t)one(q,r,h);return h;}
};
static std::vector<std::string>sp(std::string const&s){std::vector<std::string>o;std::stringstream x(s);std::string a;while(std::getline(x,a,','))o.push_back(a);return o;}static bool yy(std::string const&s){return s=="1"||(!s.empty()&&s[0]=='t');}
static std::vector<R>readr(std::string const&p){std::ifstream f(p);std::string s;std::getline(f,s);std::vector<R>o;while(std::getline(f,s)){auto a=sp(s);if(a.size()!=14)throw std::runtime_error("ray_csv_column_count");R r;r.frame=a[0];r.x=std::stoi(a[1]);r.y=std::stoi(a[2]);r.tags=a[3];r.role=a[4];r.joint=yy(a[5]);r.rgb=yy(a[6]);r.o={std::stod(a[7]),std::stod(a[8]),std::stod(a[9])};r.d={std::stod(a[10]),std::stod(a[11]),std::stod(a[12])};r.key=yy(a[13]);o.push_back(r);}return o;}
int main(int ac,char**av){try{if(ac!=5)throw std::runtime_error("usage mesh rays output topology");M m;m.load(av[1]);std::cerr<<"load "<<m.v.size()<<" source_faces="<<m.source_faces<<" triangles="<<m.t.size()<<"\n";m.topo();std::cerr<<"topology components="<<m.cs.size()<<"\n";m.n.reserve(m.t.size()/3);m.build(0,m.t.size());std::cerr<<"bvh nodes="<<m.n.size()<<"\n";auto rs=readr(av[2]);std::ofstream o(av[3]);o<<"frame_id,pixel_x,pixel_y,tags,role,joint_bad,rgb_only,hit,hit_distance,triangle_index,component_id,bary_u,bary_v,bary_w,normal_x,normal_y,normal_z,dot_ray_normal,front_facing,any_front_hit,back_facing_only,reference_b_checked,reference_b_agree\n";uint64_t ck=0,okc=0;for(size_t i=0;i<rs.size();i++){auto&r=rs[i];H h=m.cast(r);bool ok=true;if(r.key){H b=m.brute(r);ok=h.hit==b.hit&&(!h.hit||(std::abs(h.t-b.t)<1e-9&&h.id==b.id));ck++;okc+=ok;}double dn=h.hit?dot(r.d,h.n):0;o<<r.frame<<','<<r.x<<','<<r.y<<','<<r.tags<<','<<r.role<<','<<r.joint<<','<<r.rgb<<','<<h.hit<<',';if(h.hit)o<<std::setprecision(17)<<h.t<<','<<h.id<<','<<m.tcid[h.id]<<','<<h.u<<','<<h.v<<','<<1-h.u-h.v<<','<<h.n.x<<','<<h.n.y<<','<<h.n.z<<','<<dn<<','<<(dn<0);else o<<",,,,,,,,,,";o<<','<<h.front<<','<<(h.hit&&!h.front&&h.back)<<','<<r.key<<','<<ok<<"\n";if(i&&i%10000==0)std::cerr<<"rays "<<i<<"/"<<rs.size()<<"\n";}std::ofstream j(av[4]);j<<"{\n\"vertex_count\":"<<m.v.size()<<",\n\"face_count\":"<<m.source_faces<<",\n\"triangulated_face_count_for_raycast\":"<<m.t.size()<<",\n\"nontriangular_source_face_count\":"<<m.nontriangular_source_faces<<",\n\"vertex_dtype\":\"float32 x,y,z,nx,ny,nz;uint8 rgb\",\n\"face_index_dtype\":\"uint32\",\n\"bbox\":[["<<m.lo.x<<','<<m.lo.y<<','<<m.lo.z<<"],["<<m.hi.x<<','<<m.hi.y<<','<<m.hi.z<<"]],\n\"finite_vertex_count\":"<<m.finitev<<",\n\"invalid_index_count\":"<<m.invalid<<",\n\"degenerate_triangle_count\":"<<m.deg<<",\n\"zero_area_triangle_count\":"<<m.deg<<",\n\"duplicate_face_count\":"<<m.dupf<<",\n\"duplicate_vertex_count\":"<<m.dupv<<",\n\"connected_component_count\":"<<m.cs.size()<<",\n\"components\":[";for(size_t i=0;i<m.cs.size();i++){if(i)j<<',';auto&c=m.cs[i];j<<"{\"id\":"<<i<<",\"vertex_count\":"<<c.v<<",\"face_count\":"<<c.f<<",\"bbox\":[["<<c.lo.x<<','<<c.lo.y<<','<<c.lo.z<<"],["<<c.hi.x<<','<<c.hi.y<<','<<c.hi.z<<"]]}";}j<<"],\n\"boundary_edge_count\":"<<m.boundary<<",\n\"non_manifold_edge_count\":"<<m.nonman<<",\n\"watertight_indication\":"<<(m.boundary==0&&m.nonman==0?"true":"false")<<",\n\"stored_vertex_normals\":true,\n\"stored_face_normals\":false,\n\"normal_finite_count\":"<<m.normalfinite<<",\n\"winding_inconsistent_shared_edge_count\":"<<m.winding<<",\n\"signed_volume_indication\":"<<std::setprecision(17)<<m.volume<<",\n\"uv_available\":false,\n\"uv_finite_count\":0,\n\"material_texture_assignment_available\":false,\n\"reference_a\":\"task_owned_cpu_bvh_float64_moller_trumbore\",\n\"reference_b\":\"task_owned_cpu_bruteforce_float64_moller_trumbore\",\n\"reference_b_key_ray_count\":"<<ck<<",\n\"reference_b_agree_count\":"<<okc<<"\n}\n";std::cerr<<"done key="<<okc<<'/'<<ck<<"\n";}catch(std::exception const&e){std::cerr<<"ERROR "<<e.what()<<"\n";return 2;}}
